    def __init__(self, rate, burst):
        if rate <= 0:
            raise ValueError("rate must be positive")
        if burst < 1:
            raise ValueError("burst must be at least 1")
        self.rate = rate
        self.burst = burst
        # per-key state: (tokens, last_now)
        self._keys = {}

    def allow(self, key, now):
        try:
            tokens, last_now = self._keys[key]
        except KeyError:
            self._keys[key] = (float(self.burst), float(now))
            tokens = float(self.burst)
        else:
            if now < last_now:
                raise ValueError("now went backwards")
            refill = rate * (now - last_now)
            tokens = min(self.burst, tokens + refill)
            tokens = max(0.0, tokens)
            if tokens >= 1:
                tokens -= 1
                self._keys[key] = (tokens, now)
                return True
            self._keys[key] = (tokens, now)
            return False
